import{_ as e,o,c as t,a3 as r}from"./chunks/framework.DMtjdCb-.js";const l="/help/assets/work-detail.D-Zoo9T8.png",n="/help/assets/playback.DQ4HYXwH.png",g=JSON.parse('{"title":"5. 开始播放","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/playback.md","filePath":"zh-Hans/playback.md"}'),i={name:"zh-Hans/playback.md"};function s(c,a,d,p,h,m){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_5-开始播放" tabindex="-1">5. 开始播放 <a class="header-anchor" href="#_5-开始播放" aria-label="Permalink to &quot;5. 开始播放&quot;">​</a></h1><p>作品已有可访问的媒体后，在详情中选择集数和播放器即可开始观看。播放器安装在正在操作的电脑或手机上；AnimeMachine 可以运行在 NAS 上。</p><h2 id="在电脑播放一集" tabindex="-1">在电脑播放一集 <a class="header-anchor" href="#在电脑播放一集" aria-label="Permalink to &quot;在电脑播放一集&quot;">​</a></h2><ol><li>打开作品详情，找到播放区。</li><li>有多个媒体来源或 DVD / BD 版本时，先选择来源与版本。</li><li>选择开始集数，点击 <strong>使用 PotPlayer 打开</strong> 或 <strong>使用 VLC 打开</strong>。</li><li>浏览器首次询问是否打开外部应用时，选择打开。</li></ol><p><img src="'+l+'" alt="播放区：选择版本、集数和播放器" loading="lazy"></p><p><strong>完成标志：</strong> 播放器打开并开始播放选中的集数。需要连续播放多个作品时，使用<a href="./continue-watching.html">一键继续观看</a>。</p><h2 id="potplayer-记忆精确位置" tabindex="-1">PotPlayer 记忆精确位置 <a class="header-anchor" href="#potplayer-记忆精确位置" aria-label="Permalink to &quot;PotPlayer 记忆精确位置&quot;">​</a></h2><ol><li>点击 <strong>安装扩展以记忆播放进度</strong>，下载扩展包。</li><li>退出 PotPlayer，按包内 <code>README.txt</code> 将 <code>Extension</code> 目录合并到 PotPlayer 安装目录。</li><li>重新打开 PotPlayer，再从 AnimeMachine 开始播放。</li></ol><p>安装扩展后，AnimeMachine 可以记录精确位置，下次从停止位置前 5 秒续播。未安装扩展时仍可播放，按媒体访问记录集数；正在查看的作品与账户以这次生成的播放列表为准。</p><h2 id="浏览器反复询问打开播放器" tabindex="-1">浏览器反复询问打开播放器 <a class="header-anchor" href="#浏览器反复询问打开播放器" aria-label="Permalink to &quot;浏览器反复询问打开播放器&quot;">​</a></h2><p>Windows 的 Edge / Chrome 可点击 <strong>复制授权命令</strong>，按 <code>Win + R</code>，输入 <code>cmd</code> 并回车，粘贴命令运行一次，再重新打开浏览器。</p><p><img src="'+n+'" alt="播放器操作：复制授权命令与安装扩展" loading="lazy"></p><p>命令为当前 Windows 账户允许本站调用 PotPlayer 和 VLC，保留已有授权。若自动复制受阻，会显示已选中的完整命令；按 <code>Ctrl+C</code> 复制，再到 <code>cmd</code> 中运行。</p><h2 id="手机、复制地址与下载播放列表" tabindex="-1">手机、复制地址与下载播放列表 <a class="header-anchor" href="#手机、复制地址与下载播放列表" aria-label="Permalink to &quot;手机、复制地址与下载播放列表&quot;">​</a></h2><p>手机先安装 VLC，再从手机浏览器点击 <strong>使用 VLC 打开</strong>。也可以复制播放列表地址，在播放器中选择“打开网络串流”；或者下载 M3U 文件后打开。</p><p>这些方式都会保留生成列表时的账户关联，但媒体请求只能作为开始观看的线索。<strong>VLC 无法仅靠普通媒体请求精确回传停止时间</strong>；预读取也可能提前访问下一集，需要时<a href="./continue-watching.html#correct">手动纠正记录</a>。</p><p>复制的列表由生成时的集数组成。以后出现新集时，回到 AnimeMachine 重新生成列表即可。</p>',17)])])}const P=e(i,[["render",s]]);export{g as __pageData,P as default};
